import { useState, useEffect } from "react";
import "./App.css";

function App() {
  const [form, setForm] = useState({
    type: "PAYMENT",
    amount: "",
    oldbalanceOrg: "",
    newbalanceOrig: "",
    oldbalanceDest: "",
    newbalanceDest: "",
    threshold: 0.5
  });

  const [result, setResult] = useState(null);
  const [csvResults, setCsvResults] = useState(null);
  const [history, setHistory] = useState([]);
  const [stats, setStats] = useState(null);

  const fetchHistory = async () => {
    const res = await fetch("http://127.0.0.1:8000/history");
    setHistory(await res.json());
  };

  const fetchStats = async () => {
    const res = await fetch("http://127.0.0.1:8000/stats");
    setStats(await res.json());
  };

  useEffect(() => {
    fetchHistory();
    fetchStats();
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handlePredict = async () => {
    const res = await fetch("http://127.0.0.1:8000/predict", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...form,
        amount: parseFloat(form.amount),
        oldbalanceOrg: parseFloat(form.oldbalanceOrg),
        newbalanceOrig: parseFloat(form.newbalanceOrig),
        oldbalanceDest: parseFloat(form.oldbalanceDest),
        newbalanceDest: parseFloat(form.newbalanceDest),
        threshold: parseFloat(form.threshold)
      })
    });

    const data = await res.json();
    setResult(data);
    fetchHistory();
    fetchStats();
  };

  const handleCSV = async (e) => {
    const file = e.target.files[0];
    const formData = new FormData();
    formData.append("file", file);

    const res = await fetch("http://127.0.0.1:8000/predict_csv", {
      method: "POST",
      body: formData
    });

    const data = await res.json();
    setCsvResults(data);
    fetchHistory();
    fetchStats();
  };

  return (
    <div className="container">

      <h1>Fraud Detection Dashboard</h1>

      <h2>Predict a Transaction</h2>

      <div className="form-container">
        <label>Type</label>
        <select name="type" value={form.type} onChange={handleChange}>
          <option>PAYMENT</option>
          <option>CASH_IN</option>
          <option>CASH_OUT</option>
          <option>DEBIT</option>
          <option>TRANSFER</option>
        </select>

        {Object.keys(form).filter(f => f !== "type").map(key => (
          <div className="input-group" key={key}>
            <label>{key}</label>
            <input name={key} value={form[key]} onChange={handleChange} />
          </div>
        ))}

        <button onClick={handlePredict}>Predict</button>
      </div>

      {result && (
        <div className="result">
          <h2>Prediction Result</h2>
          <p><strong>Label:</strong> {result.label}</p>
          <p><strong>Prob:</strong> {result.probability.toFixed(4)}</p>
        </div>
      )}

      <hr />

      <h2>Upload CSV</h2>
      <input type="file" accept=".csv" onChange={handleCSV} />

      {csvResults && (
        <div>
          <h3>CSV Results ({csvResults.length})</h3>
        </div>
      )}

      <hr />

      <h2>Statistics</h2>
      {stats && (
        <div className="stats-box">
          <p>Total predictions: {stats.total}</p>
          <p>Frauds: {stats.frauds}</p>
          <p>Normal: {stats.normal}</p>
          <p>Fraud Rate: {(stats.fraud_rate * 100).toFixed(2)}%</p>
        </div>
      )}

      <h2>Prediction History</h2>
      <div className="history">
        {history.slice(-20).reverse().map((h, i) => (
          <div key={i} className="history-item">
            <strong>{h.label}</strong> – prob: {h.probability.toFixed(3)}
          </div>
        ))}
      </div>

    </div>
  );
}

export default App;
